import EventEmitter from 'eventemitter3';

import { AssetManager } from '@game-studio/asset-manager';

import { SoundManagerContext } from './context-handler';
import { DEFAULT_MUSIC_OPTIONS, DEFAULT_SFX_OPTIONS, DEFAULT_SOUND_MANAGER_OPTIONS } from './default-options';
import { SoundController } from './sound-controller';
import { SoundGroupController } from './sound-group-controller';
import { ExtendedAudioContextState, ISoundManagerEvents, ISoundManagerOptions, ISoundPlayOptions } from './types';

export class SoundManager extends EventEmitter<ISoundManagerEvents> {

    public static DebugLogsEnabled: boolean = false;

    public readonly controllers: Record<string, SoundGroupController> = {};

    public readonly globalController: SoundController;
    public readonly options: ISoundManagerOptions;
    private mIsUnlocked: boolean = false;

    public get music(): SoundGroupController {
        return this.controllers.music;
    }

    public get sfx(): SoundGroupController {
        return this.controllers.sfx;
    }

    public static get supportsWebAudio(): boolean {
        return SoundManagerContext.supportsWebAudio;
    }

    public static get contextState(): ExtendedAudioContextState {
        return SoundManagerContext.contextState;
    }

    private set isUnlocked(value: boolean) {
        if (value !== this.mIsUnlocked) {
            this.mIsUnlocked = value;
            this.emit('isUnlocked', value);
        }
    }

    public get isUnlocked(): boolean { return this.mIsUnlocked; }

    protected contextHandler: SoundManagerContext;

    constructor(userOptions: Partial<ISoundManagerOptions> = {}) {
        super();
        this.options = Object.assign(DEFAULT_SOUND_MANAGER_OPTIONS, userOptions);
        this.globalController = new SoundController(this.options.disablePlaybackBeforeUnlock);
        this.createCategoryController('music', DEFAULT_MUSIC_OPTIONS);
        this.createCategoryController('sfx', DEFAULT_SFX_OPTIONS);
        this.initHowler();
        this.contextHandler = new SoundManagerContext();
        document.addEventListener('visibilitychange', this.onVisibilityChange.bind(this));
        this.contextHandler.on('contextStateChange', (state) => {
            this.isUnlocked = state === 'running';
        });
        this.isUnlocked = SoundManagerContext.contextState === 'running';
    }

    public createCategoryController(category: string, defaultPlaybackOptions: ISoundPlayOptions): SoundGroupController {
        if (this.controllers[category]) {
            throw new Error(`Category [${category}] already exists as a controller in soundManager`);
        }
        this.controllers[category] = new SoundGroupController(this.globalController, {
            category: category,
            playbackOptions: defaultPlaybackOptions
        });
        return this.controllers[category];
    }

    public release(...keys: string[]): void {
        keys.forEach((key) => {
            const sound = AssetManager.sounds[key];
            this.globalController.releaseSound(key);
            sound.unload();
            delete AssetManager.sounds[key];
        });
    }

    public resume(): void {
        this.contextHandler.resume();
    }

    public suspend(): void {
        this.contextHandler.suspend();
    }

    /**
     * Stop all playing audio and empty the arrays
     */
    public stopAll(): void {
        this.globalController.stopAll();
    }

    private async onVisibilityChange(): Promise<void> {
        if (!Howler.ctx) {
            return;
        }
        if (document.visibilityState === 'visible') {
            if (this.options.stopSoundsOnVisibilityChange) {
                this.controllers.sfx.stopAll();
            }
        }
    }

    private initHowler(): void {
        Howler.autoSuspend = false;
        Howler.autoUnlock = true;
    }

    public get globalVolume(): number {
        return Howler.volume();
    }

    public set globalVolume(value: number) {
        Howler.volume(value);
    }
}